//! `fleetctl machines create` and `machines product-key store` (#489):
//! permanent, Fleet-managed VMs.
//!
//! `create` is an adapter over the reviewed `machine.create` API: it asks
//! the controller to review the spec, then runs exactly what the review
//! echoed back with the review token, and waits for the operation. Nothing
//! secret is on the command line: the SSH key is generated by the controller
//! and held in its secret store (or named by reference, or supplied as a
//! public key), and a Windows product key is read from stdin by
//! `product-key store`, which prints only the reference to use with
//! `--activate-key`.
//!
//! With `--request --purpose <why>` the command does not create anything: it
//! files an action request for a persistent machine (#496), for a caller
//! that may ask but not provision. A person approves it (or policy bounds
//! the operator configured do), and the same executor then creates the
//! machine, recording the requester and the purpose. `--wait-approval[=<d>]`
//! waits through the shared request waiter and prints the outcome and the
//! operation's result.

use std::time::Duration;

use serde_json::{Map, Value, json};

use crate::requests::parse_wait_approval;
use crate::{CliError, Output, usage};

/// The arguments of `machines create`.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
#[allow(clippy::struct_excessive_bools)]
pub struct CreateArgs {
    /// The Proxmox account.
    pub account: Option<String>,
    /// The promoted image version.
    pub image_version: Option<String>,
    /// The installer ISO volume id (`--iso`), instead of an image version.
    pub iso: Option<String>,
    /// The answer ISO volume id (`--answer-iso`).
    pub answer_iso: Option<String>,
    /// Boot with UEFI (`--efi`).
    pub efi: bool,
    /// Add a virtual TPM (`--tpm`).
    pub tpm: bool,
    /// The VM and machine name.
    pub name: Option<String>,
    /// The spec fields that map one to one.
    pub fields: Vec<(String, Value)>,
    /// Tags.
    pub tags: Vec<String>,
    /// The bootstrap login.
    pub bootstrap: Map<String, Value>,
    /// How the SSH key is chosen.
    pub credential: Option<Value>,
    /// The Windows options.
    pub windows: Map<String, Value>,
    /// The pinned host-key fingerprint.
    pub pinned: Option<String>,
    /// Only review: print the spec and token, create nothing.
    pub review_only: bool,
    /// Queue only; answer the operation instead of its outcome.
    pub no_wait: bool,
    /// A key making a retry return the operation already queued.
    pub idempotency_key: Option<String>,
    /// File an action request instead of creating (`--request`).
    pub request: bool,
    /// Why the machine is needed (`--purpose`); required with `--request`.
    pub purpose: Option<String>,
    /// How long to wait for the decision and the creation
    /// (`--wait-approval`); only with `--request`.
    pub wait: Option<Duration>,
}

fn number(name: &str, raw: &str) -> Result<u64, CliError> {
    raw.parse().map_err(|_| CliError {
        message: format!("--{name} must be a number, not {raw:?}"),
    })
}

/// Parses the flags of `machines create`.
#[allow(clippy::too_many_lines)]
pub(crate) fn parse_create(rest: &[&str], output: &mut Output) -> Result<CreateArgs, CliError> {
    let mut args = CreateArgs::default();
    let mut iter = rest.iter().copied();
    while let Some(flag) = iter.next() {
        if let Some(duration) = parse_wait_approval("--wait-approval", flag)? {
            args.wait = Some(duration);
            continue;
        }
        let mut value = |name: &str| {
            iter.next()
                .filter(|candidate| !candidate.starts_with("--"))
                .map(str::to_owned)
                .ok_or_else(|| CliError {
                    message: format!("--{name} requires a value"),
                })
        };
        match flag {
            "--output" => {
                *output = match value("output")?.as_str() {
                    "json" => Output::Json,
                    "text" => Output::Text,
                    other => {
                        return Err(CliError {
                            message: format!("--output must be json or text, not {other:?}"),
                        });
                    }
                };
            }
            "--request" => args.request = true,
            "--purpose" => args.purpose = Some(value("purpose")?),
            "--account" => args.account = Some(value("account")?),
            "--image-version" => args.image_version = Some(value("image-version")?),
            "--iso" => args.iso = Some(value("iso")?),
            "--answer-iso" => args.answer_iso = Some(value("answer-iso")?),
            "--efi" => args.efi = true,
            "--tpm" => args.tpm = true,
            "--name" => args.name = Some(value("name")?),
            "--vmid" => args
                .fields
                .push(("vmid".to_owned(), json!(number("vmid", &value("vmid")?)?))),
            "--node" => args.fields.push(("node".to_owned(), json!(value("node")?))),
            "--storage" => args
                .fields
                .push(("storage".to_owned(), json!(value("storage")?))),
            "--cores" => args.fields.push((
                "cores".to_owned(),
                json!(number("cores", &value("cores")?)?),
            )),
            "--memory" => args.fields.push((
                "memoryMib".to_owned(),
                json!(number("memory", &value("memory")?)?),
            )),
            "--disk" => args.fields.push((
                "diskGib".to_owned(),
                json!(number("disk", &value("disk")?)?),
            )),
            "--bridge" => args
                .fields
                .push(("bridge".to_owned(), json!(value("bridge")?))),
            "--audio" => args
                .fields
                .push(("audio".to_owned(), json!(value("audio")?))),
            "--tag" => args.tags.push(value("tag")?),
            "--description" => args
                .fields
                .push(("description".to_owned(), json!(value("description")?))),
            "--no-onboot" => args.fields.push(("onboot".to_owned(), json!(false))),
            "--no-protection" => args.fields.push(("protection".to_owned(), json!(false))),
            "--os" => {
                let os = value("os")?;
                if !matches!(os.as_str(), "linux" | "windows") {
                    return Err(CliError {
                        message: "--os must be linux or windows".to_owned(),
                    });
                }
                args.fields.push(("guestOs".to_owned(), json!(os)));
            }
            "--bootstrap-user" => {
                args.bootstrap
                    .insert("user".to_owned(), json!(value("bootstrap-user")?));
            }
            "--bootstrap-port" => {
                args.bootstrap.insert(
                    "port".to_owned(),
                    json!(number("bootstrap-port", &value("bootstrap-port")?)?),
                );
            }
            "--bootstrap-auth" => {
                let kind = value("bootstrap-auth")?;
                let kind = match kind.as_str() {
                    "agent" => "agent",
                    "identity-file" => "identityFile",
                    "secret" => "secret",
                    other => {
                        return Err(CliError {
                            message: format!(
                                "--bootstrap-auth must be agent, identity-file or secret, not {other:?}"
                            ),
                        });
                    }
                };
                let auth = args
                    .bootstrap
                    .entry("auth".to_owned())
                    .or_insert_with(|| json!({}));
                auth["type"] = json!(kind);
            }
            "--bootstrap-identity" => {
                let path = value("bootstrap-identity")?;
                let auth = args
                    .bootstrap
                    .entry("auth".to_owned())
                    .or_insert_with(|| json!({}));
                auth["path"] = json!(path);
            }
            "--bootstrap-credential" => {
                let credential = value("bootstrap-credential")?;
                let auth = args
                    .bootstrap
                    .entry("auth".to_owned())
                    .or_insert_with(|| json!({}));
                auth["credential"] = json!(credential);
            }
            "--pin-fingerprint" => args.pinned = Some(value("pin-fingerprint")?),
            "--credential" => {
                let credential = value("credential")?;
                args.credential = Some(if credential == "generate" {
                    json!({ "type": "generate" })
                } else {
                    json!({ "type": "reference", "credential": credential })
                });
            }
            "--public-key" => {
                args.credential = Some(json!({
                    "type": "publicKey",
                    "publicKey": value("public-key")?,
                }));
            }
            "--login-user" => args
                .fields
                .push(("loginUser".to_owned(), json!(value("login-user")?))),
            "--admin-password" => {
                let policy = value("admin-password")?;
                if !matches!(policy.as_str(), "none" | "store" | "discard") {
                    return Err(CliError {
                        message: "--admin-password must be none, store or discard".to_owned(),
                    });
                }
                args.windows
                    .insert("adminPassword".to_owned(), json!(policy));
            }
            "--activate-key" => {
                args.windows.insert(
                    "activation".to_owned(),
                    json!({ "type": "productKey", "secret": value("activate-key")? }),
                );
            }
            "--activate-kms" => {
                args.windows.insert(
                    "activation".to_owned(),
                    json!({ "type": "kms", "host": value("activate-kms")? }),
                );
            }
            "--timeout" => args.fields.push((
                "timeoutSeconds".to_owned(),
                json!(number("timeout", &value("timeout")?)?),
            )),
            "--review-only" => args.review_only = true,
            "--no-wait" => args.no_wait = true,
            "--idempotency-key" => args.idempotency_key = Some(value("idempotency-key")?),
            other => {
                return Err(CliError {
                    message: format!("unknown flag {other:?}; see the usage below\n\n{}", usage()),
                });
            }
        }
    }
    if args.image_version.is_some() == args.iso.is_some() {
        return Err(CliError {
            message: "machines create needs exactly one of --image-version and --iso".to_owned(),
        });
    }
    if args.iso.is_none() && (args.answer_iso.is_some() || args.efi || args.tpm) {
        return Err(CliError {
            message: "--answer-iso, --efi and --tpm belong to --iso".to_owned(),
        });
    }
    for (value, flag) in [(&args.account, "--account"), (&args.name, "--name")] {
        if value.is_none() {
            return Err(CliError {
                message: format!("machines create needs {flag}"),
            });
        }
    }
    if args.request {
        if args
            .purpose
            .as_deref()
            .is_none_or(|purpose| purpose.trim().is_empty())
        {
            return Err(CliError {
                message: "machines create --request needs --purpose <why the machine is needed>"
                    .to_owned(),
            });
        }
        if args.review_only || args.no_wait {
            return Err(CliError {
                message:
                    "--request files a request; it cannot be combined with --review-only or --no-wait (use --wait-approval to wait)"
                        .to_owned(),
            });
        }
    } else if args.purpose.is_some() || args.wait.is_some() {
        return Err(CliError {
            message: "--purpose and --wait-approval belong to --request".to_owned(),
        });
    }
    Ok(args)
}

impl CreateArgs {
    /// The `spec` object of the review request.
    #[must_use]
    pub fn spec(&self) -> Value {
        let mut spec = Map::new();
        spec.insert("accountId".to_owned(), json!(self.account));
        if let Some(iso) = &self.iso {
            let mut install = json!({ "iso": iso, "efi": self.efi, "tpm": self.tpm });
            if let Some(answer) = &self.answer_iso {
                install["answerIso"] = json!(answer);
            }
            spec.insert("install".to_owned(), install);
        } else {
            spec.insert("imageVersionId".to_owned(), json!(self.image_version));
        }
        spec.insert("name".to_owned(), json!(self.name));
        for (key, value) in &self.fields {
            spec.insert(key.clone(), value.clone());
        }
        if !self.tags.is_empty() {
            spec.insert("tags".to_owned(), json!(self.tags));
        }
        if !self.bootstrap.is_empty() {
            spec.insert(
                "bootstrap".to_owned(),
                Value::Object(self.bootstrap.clone()),
            );
        }
        if let Some(fingerprint) = &self.pinned {
            spec.insert(
                "hostKey".to_owned(),
                json!({ "mode": "pinned", "fingerprint": fingerprint }),
            );
        }
        if let Some(credential) = &self.credential {
            spec.insert("credential".to_owned(), credential.clone());
        }
        if !self.windows.is_empty() {
            spec.insert("windows".to_owned(), Value::Object(self.windows.clone()));
        }
        Value::Object(spec)
    }
}

/// Parses `machines abandon --account <id> --vmid <n>`.
pub(crate) fn parse_abandon(
    rest: &[&str],
    output: &mut Output,
) -> Result<crate::machine_access::MachineAccessAction, CliError> {
    let (mut account, mut vmid) = (None, None);
    let mut iter = rest.iter().copied();
    while let Some(flag) = iter.next() {
        let mut value = |name: &str| {
            iter.next().map(str::to_owned).ok_or_else(|| CliError {
                message: format!("--{name} requires a value"),
            })
        };
        match flag {
            "--output" => {
                *output = match value("output")?.as_str() {
                    "json" => Output::Json,
                    _ => Output::Text,
                };
            }
            "--account" => account = Some(value("account")?),
            "--vmid" => vmid = Some(number("vmid", &value("vmid")?)?),
            other => {
                return Err(CliError {
                    message: format!("unknown flag {other:?}; see the usage below\n\n{}", usage()),
                });
            }
        }
    }
    match (account, vmid.and_then(|vmid| u32::try_from(vmid).ok())) {
        (Some(account), Some(vmid)) => {
            Ok(crate::machine_access::MachineAccessAction::Abandon { account, vmid })
        }
        _ => Err(CliError {
            message: "machines abandon needs --account and --vmid".to_owned(),
        }),
    }
}

/// Reviews and runs the abandon of a marker.
pub(crate) fn run_abandon(
    invocation: &crate::Invocation,
    account: &str,
    vmid: u32,
) -> Result<Value, CliError> {
    let client = crate::http_client()?;
    let base = format!("/api/v1/machines/persistent/{account}/{vmid}/abandon");
    let reviewed = crate::send(
        &client,
        invocation,
        reqwest::Method::POST,
        &format!("{base}/review"),
        &[],
        None,
        uuid::Uuid::now_v7().to_string(),
    )?;
    let token = reviewed["data"]["reviewToken"]
        .as_str()
        .ok_or_else(|| CliError {
            message: "the review did not answer with a token".to_owned(),
        })?;
    crate::send(
        &client,
        invocation,
        reqwest::Method::POST,
        &base,
        &[],
        Some(&json!({ "reviewToken": token })),
        uuid::Uuid::now_v7().to_string(),
    )?;
    Ok(
        json!({ "abandoned": true, "accountId": account, "vmid": vmid, "name": reviewed["data"]["name"] }),
    )
}

/// Parses `machines persistent list` and `machines persistent register
/// --account <id> --vmid <n> [--machine <id>]`.
pub(crate) fn parse_persistent(
    rest: &[&str],
    output: &mut Output,
) -> Result<crate::machine_access::MachineAccessAction, CliError> {
    let Some((verb, flags)) = rest.split_first() else {
        return Err(CliError {
            message: format!(
                "machines persistent needs list, register or unregister\n\n{}",
                usage()
            ),
        });
    };
    let (mut account, mut vmid, mut machine, mut yes) = (None, None, None, false);
    let mut iter = flags.iter().copied();
    while let Some(flag) = iter.next() {
        let mut value = |name: &str| {
            iter.next().map(str::to_owned).ok_or_else(|| CliError {
                message: format!("--{name} requires a value"),
            })
        };
        match (*verb, flag) {
            (_, "--output") => {
                *output = match value("output")?.as_str() {
                    "json" => Output::Json,
                    _ => Output::Text,
                };
            }
            ("register" | "unregister", "--account") => account = Some(value("account")?),
            ("register" | "unregister", "--vmid") => vmid = Some(number("vmid", &value("vmid")?)?),
            ("register", "--machine") => machine = Some(value("machine")?),
            ("register" | "unregister", "--yes") => yes = true,
            (_, other) => {
                return Err(CliError {
                    message: format!("unknown flag {other:?}; see the usage below\n\n{}", usage()),
                });
            }
        }
    }
    match *verb {
        "list" => Ok(crate::machine_access::MachineAccessAction::PersistentList),
        "register" => match (account, vmid.and_then(|vmid| u32::try_from(vmid).ok())) {
            (Some(account), Some(vmid)) => Ok(
                crate::machine_access::MachineAccessAction::PersistentRegister {
                    account,
                    vmid,
                    machine,
                    yes,
                },
            ),
            _ => Err(CliError {
                message: "machines persistent register needs --account and --vmid".to_owned(),
            }),
        },
        "unregister" => match (account, vmid.and_then(|vmid| u32::try_from(vmid).ok())) {
            (Some(account), Some(vmid)) => Ok(
                crate::machine_access::MachineAccessAction::PersistentUnregister {
                    account,
                    vmid,
                    yes,
                },
            ),
            _ => Err(CliError {
                message: "machines persistent unregister needs --account and --vmid".to_owned(),
            }),
        },
        other => Err(CliError {
            message: format!(
                "unknown machines persistent command {other:?}\n\n{}",
                usage()
            ),
        }),
    }
}

/// Lists the persistent guests.
pub(crate) fn run_persistent_list(invocation: &crate::Invocation) -> Result<Value, CliError> {
    let client = crate::http_client()?;
    let body = crate::send(
        &client,
        invocation,
        reqwest::Method::GET,
        "/api/v1/machines/persistent",
        &[],
        None,
        uuid::Uuid::now_v7().to_string(),
    )?;
    Ok(json!({ "items": body["data"] }))
}

/// Reviews and runs the registration of an existing VM as persistent.
pub(crate) fn run_persistent_register(
    invocation: &crate::Invocation,
    account: &str,
    vmid: u32,
    machine: Option<&str>,
    yes: bool,
) -> Result<Value, CliError> {
    let client = crate::http_client()?;
    let base = format!("/api/v1/machines/persistent/{account}/{vmid}/register");
    let mut body = json!({});
    if let Some(machine) = machine {
        body["machineId"] = json!(machine);
    }
    let reviewed = crate::send(
        &client,
        invocation,
        reqwest::Method::POST,
        &format!("{base}/review"),
        &[],
        Some(&body),
        uuid::Uuid::now_v7().to_string(),
    )?;
    let token = reviewed["data"]["reviewToken"]
        .as_str()
        .ok_or_else(|| CliError {
            message: "the review did not answer with a token".to_owned(),
        })?;
    confirm(
        yes,
        &format!(
            "Register {} (VMID {vmid} on node {}) as a persistent machine? Lab will never select it.",
            reviewed["data"]["name"].as_str().unwrap_or("?"),
            reviewed["data"]["node"].as_str().unwrap_or("?"),
        ),
    )?;
    body["reviewToken"] = json!(token);
    let registered = crate::send(
        &client,
        invocation,
        reqwest::Method::POST,
        &base,
        &[],
        Some(&body),
        uuid::Uuid::now_v7().to_string(),
    )?;
    Ok(registered["data"].clone())
}

/// Asks for confirmation on a terminal. `--yes` skips it; without a terminal
/// and without `--yes` the answer is no.
fn confirm(yes: bool, question: &str) -> Result<(), CliError> {
    use std::io::{BufRead as _, IsTerminal as _, Write as _};
    if yes {
        return Ok(());
    }
    if !std::io::stdin().is_terminal() {
        return Err(CliError {
            message: format!("{question}\nNot confirmed: pass --yes to proceed without a terminal"),
        });
    }
    eprint!("{question} [y/N] ");
    let _ = std::io::stderr().flush();
    let mut answer = String::new();
    std::io::stdin()
        .lock()
        .read_line(&mut answer)
        .map_err(|error| CliError {
            message: format!("the answer could not be read: {error}"),
        })?;
    if matches!(answer.trim().to_ascii_lowercase().as_str(), "y" | "yes") {
        Ok(())
    } else {
        Err(CliError {
            message: "Not confirmed; nothing was changed".to_owned(),
        })
    }
}

/// Reviews and runs unregistering a registered VM.
pub(crate) fn run_persistent_unregister(
    invocation: &crate::Invocation,
    account: &str,
    vmid: u32,
    yes: bool,
) -> Result<Value, CliError> {
    let client = crate::http_client()?;
    let base = format!("/api/v1/machines/persistent/{account}/{vmid}/unregister");
    let reviewed = crate::send(
        &client,
        invocation,
        reqwest::Method::POST,
        &format!("{base}/review"),
        &[],
        None,
        uuid::Uuid::now_v7().to_string(),
    )?;
    let token = reviewed["data"]["reviewToken"]
        .as_str()
        .ok_or_else(|| CliError {
            message: "the review did not answer with a token".to_owned(),
        })?;
    confirm(
        yes,
        &format!(
            "Unregister {} (VMID {vmid})? The VM is left as it is; Lab may select it again.",
            reviewed["data"]["name"].as_str().unwrap_or("?"),
        ),
    )?;
    crate::send(
        &client,
        invocation,
        reqwest::Method::POST,
        &base,
        &[],
        Some(&json!({ "reviewToken": token })),
        uuid::Uuid::now_v7().to_string(),
    )?;
    Ok(
        json!({ "unregistered": true, "accountId": account, "vmid": vmid, "name": reviewed["data"]["name"] }),
    )
}

/// Reviews, creates and (unless `--no-wait`) waits. Answers the payload and
/// the exit code.
pub(crate) fn run_create(
    invocation: &crate::Invocation,
    args: &CreateArgs,
) -> Result<(Value, u8), CliError> {
    let client = crate::http_client()?;
    if args.request {
        let mut body = json!({
            "spec": args.spec(),
            "purpose": args.purpose,
        });
        if let Some(key) = &args.idempotency_key {
            body["idempotencyKey"] = json!(key);
        }
        let created = crate::send(
            &client,
            invocation,
            reqwest::Method::POST,
            "/api/v1/machines/create/request",
            &[],
            Some(&body),
            uuid::Uuid::now_v7().to_string(),
        )?;
        return crate::requests::finish_filed_request(&client, invocation, &created, args.wait);
    }
    let reviewed = crate::send(
        &client,
        invocation,
        reqwest::Method::POST,
        "/api/v1/machines/create/review",
        &[],
        Some(&json!({ "spec": args.spec() })),
        uuid::Uuid::now_v7().to_string(),
    )?;
    if args.review_only {
        return Ok((reviewed["data"].clone(), 0));
    }
    let token = reviewed["data"]["reviewToken"]
        .as_str()
        .ok_or_else(|| CliError {
            message: "the review did not answer with a token".to_owned(),
        })?;
    // Run exactly what the controller echoed back, so the bytes match the
    // reviewed bytes.
    let spec = reviewed["data"]["spec"].clone();
    let timeout = spec["timeoutSeconds"].as_u64().unwrap_or(1_800);
    let queued = crate::send_with_key(
        &client,
        invocation,
        reqwest::Method::POST,
        "/api/v1/machines/create",
        &[],
        Some(&json!({ "spec": spec, "reviewToken": token })),
        uuid::Uuid::now_v7().to_string(),
        args.idempotency_key.as_deref(),
    )?;
    if args.no_wait {
        return Ok((queued["data"].clone(), 0));
    }
    let operation_id = queued["data"]["id"].as_str().unwrap_or_default().to_owned();
    let (data, output) =
        crate::wait_for_operation_output(&client, invocation, &operation_id, timeout + 120)?;
    let mut payload = json!({ "operationId": operation_id, "state": data["state"] });
    if let (Some(map), Some(fields)) = (payload.as_object_mut(), output.as_object()) {
        for (key, value) in fields {
            map.insert(key.clone(), value.clone());
        }
    }
    let exit = u8::from(data["state"] != "succeeded");
    Ok((payload, exit))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn parse(rest: &[&str]) -> Result<CreateArgs, CliError> {
        parse_create(rest, &mut Output::Json)
    }

    #[test]
    fn an_iso_builds_an_install_spec_and_excludes_an_image_version() {
        let args = parse(&[
            "--account",
            "a",
            "--iso",
            "local:iso/u.iso",
            "--answer-iso",
            "local:iso/seed.iso",
            "--efi",
            "--name",
            "n",
            "--node",
            "pve",
        ])
        .unwrap();
        let spec = args.spec();
        assert_eq!(spec["install"]["iso"], "local:iso/u.iso");
        assert_eq!(spec["install"]["answerIso"], "local:iso/seed.iso");
        assert_eq!(spec["install"]["efi"], true);
        assert!(spec.get("imageVersionId").is_none());
        assert!(parse(&["--account", "a", "--name", "n"]).is_err());
        assert!(
            parse(&[
                "--account",
                "a",
                "--name",
                "n",
                "--iso",
                "x",
                "--image-version",
                "v"
            ])
            .is_err()
        );
        assert!(
            parse(&[
                "--account",
                "a",
                "--name",
                "n",
                "--image-version",
                "v",
                "--efi"
            ])
            .is_err()
        );
    }

    #[test]
    fn the_flags_build_the_spec_and_the_required_ones_are_enforced() {
        assert!(parse(&["--account", "a"]).is_err());
        let args = parse(&[
            "--account",
            "acct",
            "--image-version",
            "ver",
            "--name",
            "win-gh-runner",
            "--os",
            "windows",
            "--tag",
            "ci",
            "--no-protection",
            "--cores",
            "4",
            "--memory",
            "8192",
            "--bootstrap-auth",
            "identity-file",
            "--bootstrap-identity",
            "/keys/image",
            "--pin-fingerprint",
            "SHA256:abc",
            "--admin-password",
            "discard",
            "--activate-kms",
            "kms.example.test",
        ])
        .unwrap();
        let spec = args.spec();
        assert_eq!(spec["accountId"], "acct");
        assert_eq!(spec["guestOs"], "windows");
        assert_eq!(spec["protection"], false);
        assert_eq!(spec["cores"], 4);
        assert_eq!(spec["memoryMib"], 8192);
        assert_eq!(spec["tags"], json!(["ci"]));
        assert_eq!(
            spec["bootstrap"]["auth"],
            json!({"type": "identityFile", "path": "/keys/image"})
        );
        assert_eq!(spec["hostKey"]["mode"], "pinned");
        assert_eq!(spec["windows"]["adminPassword"], "discard");
        assert_eq!(spec["windows"]["activation"]["type"], "kms");
    }

    #[test]
    fn a_credential_flag_is_a_reference_a_public_key_or_generate() {
        let base = ["--account", "a", "--image-version", "v", "--name", "n"];
        let with = |extra: &[&str]| {
            let mut all = base.to_vec();
            all.extend_from_slice(extra);
            parse(&all).unwrap().spec()
        };
        assert!(with(&[])["credential"].is_null());
        assert_eq!(
            with(&["--credential", "generate"])["credential"]["type"],
            "generate"
        );
        assert_eq!(
            with(&["--credential", "ref-1"])["credential"],
            json!({"type": "reference", "credential": "ref-1"})
        );
        assert_eq!(
            with(&["--public-key", "ssh-ed25519 AAAA c"])["credential"]["type"],
            "publicKey"
        );
        assert!(
            parse(&[
                "--account",
                "a",
                "--image-version",
                "v",
                "--name",
                "n",
                "--bogus"
            ])
            .is_err()
        );
    }
}
